/// <summary>
/// Extension class for <c>LogisticsPostalAddressElectronicContactV2Staging</c> table.
/// Adds logic to ensure only one of Customer or Vendor account is set and updates location fields accordingly.
/// </summary>
[ExtensionOf(tableStr(LogisticsPostalAddressElectronicContactV2Staging))]
public final class AVARUMLogisticsPostalAddressElectronicContactV2Staging_Extension
{
}

Method.Source:
/// <summary>
/// Called when a field is modified on the <c>LogisticsPostalAddressElectronicContactV2Staging</c> table.
/// Ensures that only one of <c>AVACustomerAccount</c> or <c>AVAVendorAccount</c> is set.
/// Updates <c>LocationId</c> and <c>PostalAddressLocationId</c> based on the account type.
/// </summary>
/// <param name="_fieldId">The ID of the modified field.</param>
public void modifiedField(FieldId _fieldId)
{
    switch (_fieldId)
    {
        case fieldNum(LogisticsPostalAddressElectronicContactV2Staging, AVACustomerAccount):
        case fieldNum(LogisticsPostalAddressElectronicContactV2Staging, AVAVendorAccount):
            // Ensure only one of Customer or Vendor account is set
            if (this.AVACustomerAccount && this.AVAVendorAccount)
            {
                throw Global::error("@AVARUM:BothCustomerAndVendorAccountsAreSetOnlyOneIsAllowed");
            }

            // Determine account number and party type
            AccountNum accountNum = this.AVACustomerAccount ? this.AVACustomerAccount : this.AVAVendorAccount;
            AVARUMLogisticsLocationPartyType partyType = this.AVACustomerAccount ? AVARUMLogisticsLocationPartyTypeId::Customer : AVARUMLogisticsLocationPartyTypeId::Vendor;
            LogisticsLocation logisticsLocation = LogisticsPostalAddressElectronicContactV2Entity::findLogisticsLocation(partyType, accountNum);

            // Update location fields if a location is found
            if (logisticsLocation)
            {
                this.LocationId = logisticsLocation.LocationId;
                this.PostalAddressLocationId = logisticsLocation.LocationId;
            }
            break;
    }

    next modifiedField(_fieldId);
}
